abstract interface class Renderer {
  String render(String key, [Map<String, Object?> params = const {}]);
  EntityForms entity(String key);
}

final class EntityForms {
  const EntityForms({
    required this.iast,
    required this.name,
    required this.prose,
    this.short,
    this.glyph,
    this.gender,
    this.forms = const <String, String>{},
  });

  /// The forms as the boundary hands them out, whether
  /// as the JSON text or as the object it parses to.
  factory EntityForms.of(Object json) {
    final forms = json is String
        ? jsonDecode(json) as Map<String, Object?>
        : json as Map<String, Object?>;
    String? text(String form) => forms[form] as String?;
    return EntityForms(
      iast: text('iast') ?? '',
      name: text('name') ?? '',
      prose: text('prose') ?? '',
      short: text('short'),
      forms: <String, String>{
        for (final entry in forms.entries)
          if (entry.value is String) entry.key: entry.value! as String,
      },
      glyph: text('glyph'),
      gender: Gender.values
          .where((g) => g.key == text('gender'))
          .firstOrNull,
    );
  }

  final String iast;
  final String name;
  final String prose;
  final String? short;
  final String? glyph;
  final Gender? gender;
  /// Every form the locale carries, including any a loaded pack
  /// brought: a record's forms are an open set, and the fields above
  /// are only the ones `i18n/` guarantees.
  final Map<String, String> forms;
}

